from pathlib import Path
from fractions import Fraction as F
import ast,json,re,random
root=Path(__file__).parent
bank=[[],[],[]]
def evaluate(expr,x):
    expr=expr.replace('−','-').replace('＋','+').replace('－','-').replace('×','*').replace('÷','/').replace('^','**')
    expr=re.sub(r'(\d|\))(?=x|\()',r'\1*',expr)
    def walk(n):
        if isinstance(n,ast.Expression):return walk(n.body)
        if isinstance(n,ast.Constant):return F(str(n.value))
        if isinstance(n,ast.Name) and n.id=='x':return F(x)
        if isinstance(n,ast.UnaryOp):return -walk(n.operand) if isinstance(n.op,ast.USub) else walk(n.operand)
        if isinstance(n,ast.BinOp):
            a,b=walk(n.left),walk(n.right)
            if isinstance(n.op,ast.Add):return a+b
            if isinstance(n.op,ast.Sub):return a-b
            if isinstance(n.op,ast.Mult):return a*b
            if isinstance(n.op,ast.Div):return a/b
        raise ValueError(expr)
    return walk(ast.parse(expr,mode='eval'))
def q(ch,prompt,options,explanation,feedback,source='評量PDF第17–18頁概念改編',equivalent=None):
    assert len(options)==4 and len(set(options))==4 and len(feedback)==3
    if equivalent is not None:
        for x in [F(-3),F(0),F(2),F(7,3)]:
            assert evaluate(options[0],x)==evaluate(equivalent,x),(prompt,x)
        for wrong in options[1:]:
            assert any(evaluate(wrong,x)!=evaluate(equivalent,x) for x in [F(-3),F(0),F(2)]),(prompt,wrong)
    pairs=list(zip(options,[explanation]+feedback));random.Random(ch*40+len(bank[ch])+13).shuffle(pairs)
    hints=[['先分清文字表示的是幾倍、增加，還是減少；代入時需保留負數括號。','一元一次式可整理成 ax+b，x項與常數是不同類。係數是乘在x前的數。'],['先標記同類項；去括號時確認外面的符號或乘數。','分配律要乘到括號內每一項，括號前是負號時每項都要變號。'],['先用x寫出每個量的式子，確認單位與題目要求。','總量先減已知部分，再除以每份的量；最後整理同類項並用簡單數字驗算。']][ch]
    bank[ch].append(dict(prompt=prompt,options=[a for a,b in pairs],answerIndex=[a for a,b in pairs].index(options[0]),value=options[0],explanation=explanation,optionFeedback=[b for a,b in pairs],source=source,hints=hints,expr=''))

